import * as THREE from 'three';
import {GLTFLoader} from './lab/vendor/GLTFLoader.js';
import {clone} from './lab/vendor/SkeletonUtils.js';
// One WebGL context, one asset download, shared geometry, independently posed cast.
const root=new URL('.',import.meta.url),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const variants=[
 {name:'Nova',shirt:0x253a33,skin:0xffffff,hair:0x503b2c,eye:0x576f3d,background:0x15271f},
 {name:'Atlas',shirt:0x343248,skin:0xe3c4aa,hair:0x26211f,eye:0x657684,background:0x20202b,short:true,glasses:true},
 {name:'Sol',shirt:0x764d39,skin:0xa87954,hair:0x241914,eye:0x73553b,background:0x2b211a,curls:true},
 {name:'Creator',shirt:0x314b4a,skin:0xffeee0,hair:0x443128,eye:0x547b6b,background:0x182a28},
 {name:'ECHO',shirt:0x313d41,skin:0xe6d9d0,hair:0xbac3c3,eye:0x728d9a,background:0x1e2829,short:true,glasses:false}
];
let renderer,base,canvases=[],last=0,failed=false,cast=new Map(),speech={active:false,word:'',at:0};
function context(){return window.EchoCastContext}
function refresh(){canvases=[...document.querySelectorAll('canvas.face')];for(const c of canvases){c.setAttribute('aria-label',`${context()?.person(+c.dataset.face)?.name||'Character'}, 3D portrait`);if(!base)placeholder(c,failed?'Portrait unavailable':'Preparing character')}}
function placeholder(c,text){const r=c.getBoundingClientRect();if(!r.width||!r.height)return;c.width=Math.ceil(r.width);c.height=Math.ceil(r.height);const x=c.getContext('2d');x.fillStyle='#18251e';x.fillRect(0,0,c.width,c.height);x.fillStyle='#bdcdbd';x.font='13px system-ui';x.textAlign='center';x.fillText(text,c.width/2,c.height/2)}
function attachAt(bone,obj,position,model){obj.position.set(...position);model.add(obj);model.updateMatrixWorld(true);if(bone)bone.attach(obj)}
function makeCharacter(index){const v=variants[index],model=clone(base),scene=new THREE.Scene(),bones={},morphs=[];scene.background=new THREE.Color(v.background);scene.add(model);
 model.traverse(o=>{if(o.isBone)bones[o.name]={bone:o,rest:o.quaternion.clone()};if(o.isMesh){o.frustumCulled=false;if(o.morphTargetDictionary)morphs.push(o);if(o.name.includes('high-poly'))o.visible=false;if((v.short||v.curls)&&o.name.includes('ponytail'))o.visible=false;const materials=(Array.isArray(o.material)?o.material:[o.material]).map(original=>{const m=original.clone();if(m.name.includes('casual')){m.map=null;m.color.set(v.shirt);m.roughness=.85;m.metalness=.08}if(m.name.includes('body')){m.color.set(v.skin);m.roughness=.65}if(m.name.includes('ponytail')){m.color.set(v.hair);m.roughness=.85}if(m.name.includes('eyelashes')){m.color.set(0x211713);m.transparent=true;m.opacity=.65;m.depthWrite=false}if(m.name.includes('eyebrows'))m.color.set(v.hair);return m});o.material=Array.isArray(o.material)?materials:materials[0]}});
 model.updateMatrixWorld(true);
 for(const [side,x]of [['LeftEye',.0325],['RightEye',-.0325]]){const g=new THREE.Group();g.add(new THREE.Mesh(new THREE.SphereGeometry(.0168,24,16),new THREE.MeshPhysicalMaterial({color:0xf2ebe2,roughness:.18,clearcoat:1})));const iris=new THREE.Mesh(new THREE.CircleGeometry(.0068,32),new THREE.ShaderMaterial({vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'varying vec2 vUv;void main(){vec2 p=(vUv-.5)*2.0;float r=length(p);float a=atan(p.y,p.x);float fibers=sin(a*45.0+r*30.0)*.5+.5;vec3 c=mix(vec3(.08,.17,.13),vec3(.3,.45,.24),fibers);c*=1.0-smoothstep(.78,1.0,r)*.8;c=mix(c,vec3(.008,.015,.012),1.0-smoothstep(.34,.4,r));gl_FragColor=vec4(c,1.0);}'}));iris.position.z=.0163;g.add(iris);const pupil=new THREE.Mesh(new THREE.CircleGeometry(.0028,24),new THREE.MeshBasicMaterial({color:0x07110c}));pupil.position.z=.0165;g.add(pupil);const glint=new THREE.Mesh(new THREE.SphereGeometry(.0014,8,6),new THREE.MeshBasicMaterial({color:0xffffff}));glint.position.set(-.002,.0024,.0169);g.add(glint);attachAt(bones[side]?.bone,g,[x,1.6515,.129],model)}
 const hairMaterial=new THREE.MeshStandardMaterial({color:v.hair,roughness:.9});
 if(v.short){const cap=new THREE.Mesh(new THREE.SphereGeometry(1,32,18,0,Math.PI*2,0,Math.PI*.47),hairMaterial);cap.scale.set(.096,.10,.089);attachAt(bones.Head?.bone,cap,[0,1.691,.013],model);for(const x of [-.083,.083]){const side=new THREE.Mesh(new THREE.SphereGeometry(1,12,12),hairMaterial);side.scale.set(.015,.052,.061);attachAt(bones.Head?.bone,side,[x,1.699,-.006],model)}}
 if(v.curls){const hair=new THREE.Group();const geo=new THREE.SphereGeometry(.024,10,8);for(let row=0;row<6;row++){const phi=.12+row*.23;for(let j=0;j<15;j++){const a=j/15*Math.PI*2+row*.3;const curl=new THREE.Mesh(geo,hairMaterial);curl.position.set(Math.sin(phi)*Math.cos(a)*.103,Math.cos(phi)*.115,Math.sin(phi)*Math.sin(a)*.098);curl.scale.setScalar(.88+.15*Math.sin(j*8+row));hair.add(curl)}}attachAt(bones.Head?.bone,hair,[0,1.68,.003],model)}
 if(v.glasses){const glasses=new THREE.Group(),material=new THREE.MeshStandardMaterial({color:0xb8aa95,metalness:.7,roughness:.3});for(const x of [-.033,.033]){const rim=new THREE.Mesh(new THREE.TorusGeometry(.023,.0015,6,32),material);rim.scale.y=.8;rim.position.x=x;glasses.add(rim)}const bridge=new THREE.Mesh(new THREE.CylinderGeometry(.0014,.0014,.019,6),material);bridge.rotation.z=Math.PI/2;glasses.add(bridge);attachAt(bones.Head?.bone,glasses,[0,1.653,.151],model)}
 scene.add(new THREE.HemisphereLight(0xc8dfd5,0x283024,2));for(const [color,intensity,pos]of [[0xffe1be,2.8,[-1,2.5,2]],[0xc4ddff,1.1,[1,1.8,1]],[0xc7ffc4,2.8,[.5,2,-1]]]){const light=new THREE.DirectionalLight(color,intensity);light.position.set(...pos);scene.add(light)}
 const camera=new THREE.PerspectiveCamera(30,1,.05,20);camera.position.set(0,1.61,1.17);camera.lookAt(0,1.59,.04);
 return {scene,model,bones,morphs,camera,index,blinkAt:2+index*.43,blinkStart:-1,entered:performance.now(),shirt:v.shirt};
}
function pose(actor,name,x,y,z,dt){const b=actor.bones[name];if(!b)return;const q=b.rest.clone().multiply(new THREE.Quaternion().setFromEuler(new THREE.Euler(x,y,z)));b.bone.quaternion.slerp(q,1-Math.exp(-8*dt))}
function animate(actor,t,dt,talking){const s=context().state(),v={},i=actor.index;const blinkPeriod=3.6+i*.41,blinkPhase=(t+i*.6)%blinkPeriod;v.eyeBlinkLeft=v.eyeBlinkRight=blinkPhase<.15?Math.sin(blinkPhase/.15*Math.PI):0;
 if(talking){if(s.voice){if(speech.active){const word=speech.word.toLowerCase();const key=/^[bmp]/.test(word)?'PP':/^[fv]/.test(word)?'FF':/^[ou]/.test(word)?'O':'aa';v['viseme_'+key]=.2+.45*Math.abs(Math.sin(t*13));}}else{v.viseme_aa=.2+.3*Math.abs(Math.sin(t*10));v.viseme_E=.12*Math.max(0,Math.sin(t*7))}v.browInnerUp=.1+.08*Math.sin(t*2)}else if(i===1){v.browDownLeft=.15;v.browOuterUpRight=.18}else{v.mouthSmileLeft=.08;v.mouthSmileRight=.08}
 const reaction=s.reaction&&s.reaction.until>performance.now();if(reaction){if(s.reaction.symbol==='Egg'){v.eyeBlinkLeft=v.eyeBlinkRight=.55;v.browDownLeft=.25}else{v.mouthSmileLeft=v.mouthSmileRight=.55;v.cheekSquintLeft=v.cheekSquintRight=.15}}
 for(const m of actor.morphs)for(const [name,idx]of Object.entries(m.morphTargetDictionary))m.morphTargetInfluences[idx]=THREE.MathUtils.damp(m.morphTargetInfluences[idx],v[name]||0,18,dt);
 const idle=reduce?0:Math.sin(t*.65+i)*.025;pose(actor,'Head',talking&&!reduce?Math.sin(t*2)*.02:0,idle,talking?0:idle*.7,dt);pose(actor,'Spine2',reduce?0:Math.sin(t)*.006,0,0,dt);pose(actor,'LeftArm',0,0,-.13,dt);pose(actor,'RightArm',0,0,.13,dt);
 if(i===3){const style=s.avatar&&document.querySelector('#overlay').hidden?s.avatar.color:s.draft.color;const color=variants[style||0].shirt;if(actor.shirt!==color){actor.model.traverse(o=>{if(o.isMesh)for(const m of Array.isArray(o.material)?o.material:[o.material])if(m.name.includes('casual'))m.color.set(color)});actor.shirt=color}}
}
function frame(ms){requestAnimationFrame(frame);if(document.hidden||!base||failed||ms-last<40)return;const dt=Math.min((ms-last)/1000,.05);last=ms;canvases=canvases.filter(c=>c.isConnected);const ctx=context();if(!ctx)return;const s=ctx.state(),who=ctx.current()[0],speaker=typeof who==='number'?(who===2&&s.onStage?3:who):4;const active=new Set();for(const c of canvases){const r=c.getBoundingClientRect();if(!r.width||!r.height||r.bottom<0||r.top>innerHeight||!c.checkVisibility?.({checkVisibilityCSS:true})&&getComputedStyle(c).visibility==='hidden')continue;const i=Number(c.dataset.face);if(!variants[i])continue;let actor=cast.get(i);if(!actor){actor=makeCharacter(i);cast.set(i,actor)}if(!active.has(i)){animate(actor,ms/1000,dt,s.view==='watch'&&s.playing&&speaker===i&&document.querySelector('#overlay').hidden);active.add(i)}const dpr=Math.min(devicePixelRatio||1,1.25),w=Math.max(1,Math.round(r.width*dpr)),h=Math.max(1,Math.round(r.height*dpr));if(c.width!==w||c.height!==h){c.width=w;c.height=h}actor.camera.aspect=w/h;actor.camera.updateProjectionMatrix();renderer.render(actor.scene,actor.camera);const out=c.getContext('2d');out.clearRect(0,0,w,h);out.drawImage(renderer.domElement,0,0,w,h);if(!reduce){const alpha=Math.min(1,(ms-actor.entered)/1000);if(alpha<1){out.fillStyle=`rgba(20,35,27,${1-alpha})`;out.fillRect(0,0,w,h)}}}}
window.EchoCast={refresh,setSpeech(active,word=''){speech={active,word,at:performance.now()}},getState:()=>({ready:!!base,failed,characters:cast.size})};window.initFaces=refresh;
window.addEventListener('echo:portraits',refresh);
async function start(){refresh();try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true,powerPreference:'default'});renderer.setPixelRatio(1);renderer.setSize(innerWidth<760?400:640,innerWidth<760?520:800,false);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.9;renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();failed=true;refresh()});const gltf=await new GLTFLoader().loadAsync(new URL('lab/assets/nova.glb',root).href);base=gltf.scene;refresh();requestAnimationFrame(frame)}catch(error){console.error('Character renderer could not start',error);failed=true;refresh();window.dispatchEvent(new CustomEvent('echo:portrait-error'))}}
start();
